gBw(){return"\u06af\u06d5\u0695\u0627\u0646\u06d5\u0648\u06d5 \u0628\u06c6 \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5"},
gadP(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u062a \u0644\u06d5\u0628\u06cc\u0631\u0686\u0648\u0648\u06d5\u061f"},
gabM(){return"\u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u062f\u0627\u0646\u0627\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gabL(){return"\u0626\u06cc\u0645\u06d5\u06cc\u06b5\u06d5\u06a9\u06d5\u062a \u0628\u0646\u0648\u0648\u0633\u06d5 \u0648 \u0626\u06ce\u0645\u06d5 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06ce\u06a9\u062a \u0628\u06c6 \u062f\u06d5\u0646\u06ce\u0631\u06cc\u0646 \u0628\u06c6 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u062f\u0627\u0646\u0627\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc."},
gabJ(){return"\u0646\u0627\u0631\u062f\u0646\u06cc \u0628\u06d5\u0633\u062a\u06d5\u0631\u06cc \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u062f\u0627\u0646\u0627\u0646\u06d5\u0648\u06d5"},
gabK(){return"\u0626\u06d5\u06af\u06d5\u0631 \u0647\u06d5\u0698\u0645\u0627\u0631\u06ce\u06a9 \u0628\u06c6 \u0626\u06d5\u0648 \u0626\u06cc\u0645\u06d5\u06cc\u06b5\u06d5 \u0647\u06d5\u0628\u06ce\u062a\u060c \u0628\u06d5\u0633\u062a\u06d5\u0631\u06cc \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u062f\u0627\u0646\u0627\u0646\u06d5\u0648\u06d5 \u0628\u06d5\u0645 \u0632\u0648\u0648\u0627\u0646\u06d5 \u062f\u06d5\u06af\u0627\u062a\u06ce."},
gabI(){return"\u0626\u06cc\u0645\u06d5\u06cc\u06b5\u06d5\u06a9\u06d5\u062a \u0628\u0646\u0648\u0648\u0633\u06d5"},
galH(){return"\u062f\u0627\u0646\u0627\u0646\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce"},
galF(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06d5\u06a9\u06cc \u0646\u0648\u06ce \u0628\u06c6 \u0647\u06d5\u0698\u0645\u0627\u0631\u06d5\u06a9\u06d5\u062a \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5."},
galD(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce"},
galB(){return"\u062f\u0648\u0648\u067e\u0627\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce"},
galE(){return"\u0646\u0648\u06ce\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
galG(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce\u06a9\u0631\u0627\u06cc\u06d5\u0648\u06d5. \u062a\u06a9\u0627\u06cc\u06d5 \u0628\u06d5 \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce \u0628\u0686\u06c6\u0631\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5."},
gamu(){return"\u0686\u06d5\u0646\u0627\u06af\u06d5\u06cc \u062a\u06d5\u0648\u0627\u0648 / \u0646\u06cc\u06cc\u06d5"},
gamq(){return"\u067e\u06ce\u0634\u062a\u0631 \u0628\u06c6 \u062c\u06c6\u0631\u06ce\u06a9\u06cc \u062a\u0631 \u0644\u06d5\u0645 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u062f\u0627 \u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u0627\u0648\u06d5"},
gamv(){return"\u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u0645 \u0686\u0627\u0631\u06d5\u06a9\u06d5 \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u06d5 \u06cc\u0627\u0646 \u0644\u0627\u0628\u062f\u06d5"},
gams(){return"\u0628\u06d5\u0633\u062a\u0646\u06d5\u0648\u06d5\u06cc \u0626\u06d5\u0645 \u062f\u0648\u0648 \u062f\u062f\u0627\u0646\u06d5 (\u067e\u0631\u062f)"},
gamt(){return"\u067e\u0631\u062f. \u06a9\u0631\u062a\u06d5 \u0628\u06a9\u06d5 \u0628\u06c6 \u062c\u06cc\u0627\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5"},
gamr(){return"\u06a9\u0631\u062a\u06d5 \u0644\u06d5 \u0628\u0627\u0632\u0646\u06d5\u06cc \u0646\u06ce\u0648\u0627\u0646 \u062f\u0648\u0648 \u062f\u062f\u0627\u0646 \u0628\u06a9\u06d5 \u0628\u06c6 \u0628\u06d5\u0633\u062a\u0646\u06d5\u0648\u06d5\u06cc\u0627\u0646 \u0648\u06d5\u06a9 \u067e\u0631\u062f. \u0626\u06d5\u06af\u06d5\u0631 \u062c\u06cc\u0627\u0646\u060c \u0628\u06d5 \u0628\u06d5\u062a\u0627\u06b5\u06cc \u062c\u06ce\u06cc \u0628\u0647\u06ce\u06b5\u06d5."},
